if(type==='hubble'){const tube=cyl(.46,.46,2.15,0xa3b2bf,0,0,0);const rim=cyl(.48,.48,.08,white,0,1.12,0);const aperture=cyl(.41,.41,.015,dark,0,1.165,0);const lid=cyl(.47,.47,.05,0xa3b2bf,0,1.36,-.4);lid.rotation.x=.95;for(const side of [-1,1]){rod([side*.4,-.2,0],[side*1.55,-.2,0],.035,white);box(.85,1.4,.045,0x1b3653,side*1.18,-.2,0);for(let j=0;j<6;j++)box(.86,.015,.05,0x7d8f9e,side*1.18,-.83+j*.25,0);box(.018,1.4,.05,0x7d8f9e,side*1.18,-.2,0)}root.rotation.set(.65,0,-.5)}
